    cy.window({ log: false })
        .then((win) => {
            const elems = win.document.body.getElementsByTagName('*');
            const images = [];
            let counter = 0;

            Array.prototype.forEach.call(elems, (elem) => {
                if (elem.tagName === 'IMG') {
                    if (!elem.completed) {
                        images.push(elem);
                    }
                } else {
                    const styles = win.getComputedStyle(elem);
                    const backgroundImage = styles.getPropertyValue('background-image');
                    const matchedUrl = backgroundImage.match(/url\((.*)\)/);
                    if (matchedUrl) {
                        const image = new Image();
                        image.src = matchedUrl[1];
                        if (!image.completed) {
                            images.push(image);
                        }
                    }
                }
            });

            if (!images.length) {
                return Cypress.Promise.resolve();
            }

            return new Cypress.Promise((resolve) => {
                images.forEach((image) => {
                    image.addEventListener('load', incrementCounter, false);
                    image.addEventListener('error', incrementCounter, false);
                });

                function incrementCounter() {
                    counter++;
                    if (counter === images.length) {
                        resolve();
                    }
