/**
 * Use Cypress environment variables to set the `baseUrl` configuration
 * parameter (used for `cy.visit()` and `cy.request()`).
 *
 * The Cypress launchers we use from package.json may set OS environment
 * variables CYPRESS_MONITOR_MOCKSERVER_PORT and CYPRESS_MONITOR_PROXY_PORT.
 * These variables are accessible from Cypress without the CYPRESS_ prefix.
 *
 * One of these 2 variables is used, if defined, depending on the kind of
 * test being run (UI or E2E).
 */
export const setBaseUrl = () => {
	let isUITest = Cypress.spec.name.match(/_spec.ui.js/);
	let isComponentTest = Cypress.spec.relative.match(/cypress\/component/);

	if (isUITest || isComponentTest) {
		setBaseUrlFromPortEnvVariable("MONITOR_MOCKSERVER_PORT");
	} else {
		setBaseUrlFromPortEnvVariable("MONITOR_PROXY_PORT");
	}
};

/**
 * Use the Cypress environment variable named `name`, if defined, to
 * set the `baseUrl` configuration parameter (used for `cy.visit()` and
 * `cy.request()`).
 */
const setBaseUrlFromPortEnvVariable = (name) => {
	let port = Cypress.env(name);

	if (port) {
