This issue pertains to a WebGL2 library I am developing, it is a browser-only library.

When creating 7 or more webgl buffers within Chrome 90, Chrome 96, Chrome 98 or Edge 98 a webgl context loss occurs if the browser is being controlled by Cypress. The context loss does not occur in Firefox 96 or any of the previously mentioned browsers when they're launched normally (ie, not via Cypress).

### Desired behavior

Cypress runs the provided code without a context loss occuring.

### Test code to reproduce

```js
describe('webgl', () => {
  it('works', async () => {
    let canvas = document.createElement('canvas')
    let gl = canvas.getContext('webgl2')

    function createBuffer() {
      let buf = gl.createBuffer()
      let byteLength = 16
      gl.bindBuffer(gl.ARRAY_BUFFER, buf)
      gl.bufferData(gl.ARRAY_BUFFER, byteLength, gl.DYNAMIC_COPY)
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, new Uint32Array([0, 1, 2, 3]))
      gl.bindBuffer(gl.ARRAY_BUFFER, null)
      return buf
    }

    async function waitForIdle() {
      let sync = gl.fenceSync(gl.SYNC_GPU_COMMANDS_COMPLETE, 0)
      gl.flush()
      await new Promise((resolve) => {
        function test() {
          if (gl.clientWaitSync(sync, 0, 0) === gl.TIMEOUT_EXPIRED) setTimeout(test, 10)
          else resolve()
        }
        test()
      })
      gl.deleteSync(sync)
    }

    async function main() {
      for (let i = 0; i < 10; i++) {
        createBuffer()
        await waitForIdle()
        console.log(i, gl.isContextLost())
      }
    }

    await main()
  })
})
